final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Creates an AWS IoT Core policy for device onboarding where the policy allows
  devices to connect, publish, and subscribe to topics scoped to their own thing
  name. The policy is created via a Lambda-backed custom resource running
  Node.js 24.x and its generated name is exported as a stack output.

Parameters:
  PolicyNamePrefix:
    Type: String
    Default: DeviceOnboarding
    Description: Prefix used to build the generated IoT policy name.

Resources:
  # IAM Role that grants the AWS Lambda function permission to execute and to
  # manage IoT Core policies.
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - lambda.amazonaws.com
            Action:
              - sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IotPolicyLifecycle
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:GetPolicy
                  - iot:DeletePolicy
                Resource: '*'

  # Lambda function (Node.js 24.x) that backs the custom resource. On Create it
  # provisions the IoT policy; on Delete it cleans it up.
  PolicyCreatorFunction:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName:
        Fn::Sub: ${AWS::StackName}-iot-policy-creator
      Handler: index.handler
      Runtime: nodejs24.x
      Role:
        Fn::GetAtt:
          - LambdaExecutionRole
          - Arn
      Timeout: 120
      MemorySize: 256
      Code:
        ZipFile: |
          const https = require('https');
          const {
            IoTClient,
            CreatePolicyCommand,
            DeletePolicyCommand,
            ResourceNotFoundException
          } = require('@aws-sdk/client-iot');

          const REGION = process.env.AWS_REGION;
          const iot = new IoTClient({ region: REGION });

          function sanitize(name) {
            return name.replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 128);
          }

          function getAccountId(event) {
            return event.ServiceToken.split(':')[4];
          }

          function makeIotArn(kind, resource, accountId) {
            return `arn:aws:iot:${REGION}:${accountId}:${kind}/${resource}`;
          }

          function buildPolicyDocument(accountId) {
            return JSON.stringify({
              Version: '2012-10-17',
              Statement: [
                {
                  Effect: 'Allow',
                  Action: 'iot:Connect',
                  Resource: makeIotArn(
                    'client',
                    '${iot:Connection.Thing.ThingName}',
                    accountId
                  )
                },
                {
                  Effect: 'Allow',
                  Action: 'iot:Publish',
                  Resource: makeIotArn(
                    'topic',
                    '${iot:Connection.Thing.ThingName}/*',
                    accountId
                  )
                },
                {
                  Effect: 'Allow',
                  Action: 'iot:Subscribe',
                  Resource: makeIotArn(
                    'topicfilter',
                    '${iot:Connection.Thing.ThingName}/*',
                    accountId
                  )
                },
                {
                  Effect: 'Allow',
                  Action: 'iot:Receive',
                  Resource: makeIotArn(
                    'topic',
                    '${iot:Connection.Thing.ThingName}/*',
                    accountId
                  )
                }
              ]
            });
          }

          function sendResponse(event, context, status, physicalResourceId, data, error) {
            const body = JSON.stringify({
              Status: status,
              Reason: error ? `${error.name}: ${error.message}` : '',
              PhysicalResourceId: physicalResourceId,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              Data: data || {}
            });

            return new Promise((resolve, reject) => {
              const url = new URL(event.ResponseURL);
              const request = https.request(
                {
                  hostname: url.hostname,
                  path: url.pathname + url.search,
                  method: 'PUT',
                  headers: {
                    'Content-Type': '',
                    'Content-Length': Buffer.byteLength(body)
                  }
                },
                (response) => {
                  response.resume();
                  resolve(body);
                }
              );
              request.on('error', reject);
              request.write(body);
              request.end();
            });
          }

          exports.handler = async (event, context) => {
            const props = event.ResourceProperties;
            const accountId = getAccountId(event);
            let physicalResourceId = event.PhysicalResourceId;
            let data = {};
            let status = 'SUCCESS';
            let error;

            try {
              if (event.RequestType === 'Create') {
                const prefix = sanitize(props.PolicyNamePrefix);
                const policyName = sanitize(
                  `${prefix}-${event.RequestId}`
                ).slice(0, 128);
                const policyDocument = buildPolicyDocument(accountId);
                await iot.send(
                  new CreatePolicyCommand({
                    policyName,
                    policyDocument
                  })
                );
                physicalResourceId = policyName;
                data = { PolicyName: policyName };
              } else if (event.RequestType === 'Update') {
                physicalResourceId = event.PhysicalResourceId;
                data = { PolicyName: physicalResourceId };
              } else if (event.RequestType === 'Delete') {
                try {
                  await iot.send(
                    new DeletePolicyCommand({
                      policyName: event.PhysicalResourceId
                    })
                  );
                } catch (deleteErr) {
                  if (
                    !deleteErr ||
                    deleteErr.name !== ResourceNotFoundException.name
                  ) {
                    throw deleteErr;
                  }
                }
                physicalResourceId = event.PhysicalResourceId;
                data = {};
              }
            } catch (err) {
              console.error('Custom resource processing failed:', err);
              status = 'FAILED';
              data = {};
              error = err;
            }

            await sendResponse(
              event,
              context,
              status,
              physicalResourceId,
              data,
              error
            );
          };
      Description: >-
        Custom resource Lambda that creates the per-thing-scoped IoT Core policy
        for device onboarding.

  # Custom resource that invokes the Lambda to create the IoT policy and return
  # its generated name.
  IoTOnboardingPolicy:
    Type: AWS::CloudFormation::CustomResource
    Properties:
      ServiceToken:
        Fn::GetAtt:
          - PolicyCreatorFunction
          - Arn
      PolicyNamePrefix:
        Ref: PolicyNamePrefix
    DependsOn:
      - PolicyCreatorFunction

Outputs:
  PolicyName:
    Description: The generated AWS IoT Core policy name for device onboarding.
    Value:
      Fn::GetAtt:
        - IoTOnboardingPolicy
        - PolicyName

AWSTemplateFormatVersion: "2010-09-09"
Description: "Amazon Verified Permissions policy store implementing Cedar-based access control for a bookstore application."

Parameters:
  ForbiddenAdminName:
    Type: String
    Default: admin_doe
    Description: "Name of the specific administrator explicitly forbidden from viewing books."
  SpecificUserName:
    Type: String
    Default: alice
    Description: "Name of the specific user permitted to view a specific book."
  SpecificBookName:
    Type: String
    Default: the_great_gatsby
    Description: "Name of the specific book a specific user is allowed to view."

Resources:
  # --------------------------------------------------------------------------
  # Policy Store with strict schema validation
  # --------------------------------------------------------------------------
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: "Policy store for the Bookstore application using Cedar-based access control."
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |-
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "memberOfTypes": [],
                  "shape": { "type": "Record", "attributes": {} }
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": { "type": "Long" }
                    }
                  }
                },
                "Book": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": { "type": "Entity", "name": "Bookstore::User" }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [ "User" ],
                    "resourceTypes": [ "Book" ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": { "type": "String" }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [ "User" ],
                    "resourceTypes": [ "Book" ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": { "type": "String" }
                      }
                    }
                  }
                }
              }
            }
          }

  # --------------------------------------------------------------------------
  # Static Cedar policies
  # --------------------------------------------------------------------------
  # 1. Permit users in the Admin role to view any book.
  AdminCanViewAnyBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |-
            permit(
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource is Bookstore::Book
            );

  # 2. Explicitly forbid one specific named administrator from viewing books,
  #    overriding the general admin permission.
  ForbidSpecificAdminViewingBooks:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: !Sub |-
            forbid(
              principal == Bookstore::User::"${ForbiddenAdminName}",
              action == Bookstore::Action::"View",
              resource is Bookstore::Book
            );

  # 3. Permit users in the Publisher role to view only the books they own.
  PublisherCanViewOwnedBooks:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |-
            permit(
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            ) when {
              resource.owner == principal
            };

  # 4. Permit one specific named user to view one specific named book.
  SpecificUserCanViewSpecificBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: !Sub |-
            permit(
              principal == Bookstore::User::"${SpecificUserName}",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"${SpecificBookName}"
            );

  # 5. Permit users in the Customer role to view premium offers once they have
  #    been a member for two years or more.
  CustomerCanViewPremiumOffers:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |-
            permit(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            ) when {
              principal.yearsAsMember >= 2
            };

  # 6. Forbid customers with less than two years of membership from viewing
  #    premium offers.
  ForbidCustomersWithLessThanTwoYearsPremiumOffers:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |-
            forbid(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            ) unless {
              principal.yearsAsMember >= 2
            };

  # 7. Forbid View and ViewWithPremiumOffers actions entirely whenever the
  #    request context's region is not the United States.
  ForbidNonUsRegionActions:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |-
            forbid(
              principal,
              action in [ Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            ) unless {
              context.region == "US"
            };

  # --------------------------------------------------------------------------
  # Publish the policy store ID as an SSM parameter
  # --------------------------------------------------------------------------
  BookstorePolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/policy-store-id
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: "The Amazon Verified Permissions policy store ID for the bookstore application."

Outputs:
  PolicyStoreId:
    Description: "The Amazon Verified Permissions policy store ID for the bookstore application."
    Value: !Ref BookstorePolicyStore
  PolicyStoreArn:
    Description: "The Amazon Resource Name (ARN) of the bookstore policy store."
    Value: !GetAtt BookstorePolicyStore.Arn

AWSTemplateFormatVersion: "2010-09-09"
Description: "Step Functions Calculator Demo — routes arithmetic operations through a
  choice state to a Lambda function and fails on unknown operators."

Resources:

  # ---------------------------------------------------------------------------
  # Lambda Function (Node.js 20.x, inline code)
  # ---------------------------------------------------------------------------
  CalculatorFunction:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: Calculator
      Runtime: nodejs24.x
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Code:
        ZipFile: |
          exports.handler = async (event) => {
              const { operator, operands } = event;
              if (!operator || !operands || !Array.isArray(operands) || operands.length !== 2) {
                  throw new Error('Invalid input: expected {"operator": "...", "operands": [a, b]}');
              }
              const [a, b] = operands;
              let result;
              switch (operator) {
                  case 'add':
                      result = a + b;
                      break;
                  case 'subtract':
                      result = a - b;
                      break;
                  case 'multiply':
                      result = a * b;
                      break;
                  case 'divide':
                      if (b === 0) throw new Error('Division by zero');
                      result = a / b;
                      break;
                  default:
                      throw new Error('Unknown operator: ' + operator);
              }
              return { operator, operands, result };
          };

  # ---------------------------------------------------------------------------
  # CloudWatch Log Group for Lambda (3-day retention)
  # ---------------------------------------------------------------------------
  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: 3

  # ---------------------------------------------------------------------------
  # IAM Role for Lambda – allows writing logs to CloudWatch
  # ---------------------------------------------------------------------------
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: LambdaLoggingPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                Resource: !Sub "arn:aws:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/lambda/Calculator"
              - Effect: Allow
                Action:
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: !Sub "arn:aws:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/lambda/Calculator:log-stream:*"

  # ---------------------------------------------------------------------------
  # IAM Role for Step Functions – allows invoking the Calculator Lambda
  # ---------------------------------------------------------------------------
  StateMachineExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: StateMachineInvokeLambdaPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action: lambda:InvokeFunction
                Resource: !GetAtt CalculatorFunction.Arn

  # ---------------------------------------------------------------------------
  # Step Functions State Machine – Calculator-StateMachine
  # ---------------------------------------------------------------------------
  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      RoleArn: !GetAtt StateMachineExecutionRole.Arn
      DefinitionString:
        Fn::Sub:
          - |-
            {
              "Comment": "Calculator State Machine",
              "StartAt": "ChooseOperation",
              "States": {
                "ChooseOperation": {
                  "Type": "Choice",
                  "Choices": [
                    {
                      "Variable": "$.operator",
                      "StringEquals": "add",
                      "Next": "Add"
                    },
                    {
                      "Variable": "$.operator",
                      "StringEquals": "subtract",
                      "Next": "Subtract"
                    },
                    {
                      "Variable": "$.operator",
                      "StringEquals": "multiply",
                      "Next": "Multiply"
                    },
                    {
                      "Variable": "$.operator",
                      "StringEquals": "divide",
                      "Next": "Divide"
                    }
                  ],
                  "Default": "UnknownOperator"
                },
                "Add": {
                  "Type": "Task",
                  "Resource": "arn:aws:states:::lambda:invoke",
                  "Parameters": {
                    "FunctionName": "${LambdaArn}",
                    "Payload": {
                      "operator.$": "$.operator",
                      "operands.$": "$.operands"
                    }
                  },
                  "ResultPath": "$.result",
                  "End": true
                },
                "Subtract": {
                  "Type": "Task",
                  "Resource": "arn:aws:states:::lambda:invoke",
                  "Parameters": {
                    "FunctionName": "${LambdaArn}",
                    "Payload": {
                      "operator.$": "$.operator",
                      "operands.$": "$.operands"
                    }
                  },
                  "ResultPath": "$.result",
                  "End": true
                },
                "Multiply": {
                  "Type": "Task",
                  "Resource": "arn:aws:states:::lambda:invoke",
                  "Parameters": {
                    "FunctionName": "${LambdaArn}",
                    "Payload": {
                      "operator.$": "$.operator",
                      "operands.$": "$.operands"
                    }
                  },
                  "ResultPath": "$.result",
                  "End": true
                },
                "Divide": {
                  "Type": "Task",
                  "Resource": "arn:aws:states:::lambda:invoke",
                  "Parameters": {
                    "FunctionName": "${LambdaArn}",
                    "Payload": {
                      "operator.$": "$.operator",
                      "operands.$": "$.operands"
                    }
                  },
                  "ResultPath": "$.result",
                  "End": true
                },
                "UnknownOperator": {
                  "Type": "Fail",
                  "Error": "UnknownOperatorError",
                  "Cause": "The specified operator is not supported. Supported operators: add, subtract, multiply, divide"
                }
              }
            }
          - {LambdaArn: !GetAtt CalculatorFunction.Arn}

Outputs:
  SampleInput:
    Description: Sample input format for the Calculator state machine
    Value: '{"operator": "add", "operands": [1, 2]}'
  CalculatorStateMachineArn:
    Description: ARN of the Calculator State Machine
    Value: !Ref CalculatorStateMachine
  CalculatorFunctionArn:
    Description: ARN of the Calculator Lambda Function
    Value: !GetAtt CalculatorFunction.Arn
